const e=JSON.parse('{"key":"v-50d27c9c","path":"/Framework/Electron/electron02.html","title":"Electron 实现跨窗口免登功能","lang":"zh-CN","frontmatter":{"title":"Electron 实现跨窗口免登功能","icon":"electron","date":"2024-03-22T00:00:00.000Z","category":["框架"],"tag":["electron"],"star":false,"sticky":false},"headers":[{"level":2,"title":"实现原理","slug":"实现原理","link":"#实现原理","children":[]},{"level":2,"title":"实现步骤","slug":"实现步骤","link":"#实现步骤","children":[{"level":3,"title":"1. 修改渲染进程（App.vue）","slug":"_1-修改渲染进程-app-vue","link":"#_1-修改渲染进程-app-vue","children":[]},{"level":3,"title":"2. 修改主进程（index.ts）","slug":"_2-修改主进程-index-ts","link":"#_2-修改主进程-index-ts","children":[]},{"level":3,"title":"3. 修改预加载脚本（preload/index.ts）","slug":"_3-修改预加载脚本-preload-index-ts","link":"#_3-修改预加载脚本-preload-index-ts","children":[]},{"level":3,"title":"4. 修改类型定义文件（preload/index.d.ts）","slug":"_4-修改类型定义文件-preload-index-d-ts","link":"#_4-修改类型定义文件-preload-index-d-ts","children":[]}]},{"level":2,"title":"遇到的问题与解决方案","slug":"遇到的问题与解决方案","link":"#遇到的问题与解决方案","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"git":{"createdTime":1774172875000,"updatedTime":1774172875000,"contributors":[{"name":"rayadaschn","email":"115447518+rayadaschn@users.noreply.github.com","commits":1}]},"readingTime":{"minutes":6.31,"words":1894},"filePathRelative":"Framework/Electron/electron02.md","localizedDate":"2024年3月22日","excerpt":"<p>在开发 Electron 应用时，跨窗口免登是一个常见的需求。本文将详细介绍如何利用 Electron 的 session 模块操作 cookie 实现这一功能。</p>\\n<figure><img src=\\"https://cdn.jsdelivr.net/gh/rayadaschn/blogImage@master/img/electron_login.gif\\" alt=\\"跨窗口免登录\\" tabindex=\\"0\\" loading=\\"lazy\\"><figcaption>跨窗口免登录</figcaption></figure>\\n<h2> 实现原理</h2>\\n<p>Electron 应用中的所有窗口默认共享同一个会话（session），这是实现跨窗口免登的基础。通过在会话中设置认证 cookie，当用户打开新窗口时，新窗口会自动继承该会话的 cookie，从而保持登录状态。</p>"}');export{e as data};
